    let mut shared_value = RefCell::new(5); // Création d'une valeur partagée avec une espace intérieur mutable

    // On peut maintenant muter la valeur internale de la cellule
    *shared_value.borrow_mut() = 10; // Utilisation du borrow_mut pour obtenir un mut ref au contenu

    println!("La valeur partagée est: {}", shared_value.borrow()); // Affichage de la valeur partagée
}
```

